insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mt1_v1'
from (values
('117.319.c.1.A',2,'Before a musical rehearsal, the cast stretches, hums scales and walks through simple dance steps. This routine prepares what?','["Voice, body and dance skills for performing", "The program order", "The costume shop", "The ticket booth"]'::jsonb,0,'Musical theatre warm-ups cover singing, acting and dance.','original'),
('117.319.c.1.A',2,'Which vocal warm-up is useful before singing in a musical?','["Shouting over a crowd", "Sirens and gentle lip trills", "Singing at full volume cold", "Whispering only"]'::jsonb,1,'Gentle exercises prepare the voice.','original'),
('117.319.c.1.B',2,'A performer uses small, expressive hand gestures to tell a story without speaking. This skill is ___.','["Aria", "Soliloquy", "Pantomime", "Recitative"]'::jsonb,2,'Pantomime tells a story through gesture.','original'),
('117.319.c.1.B',2,'Which dance genre is often featured in a musical''s tap number?','["Folk waltz only", "Marching", "Square dancing", "Tap"]'::jsonb,3,'Tap dance is common in musicals.','original'),
('117.319.c.1.C',3,'A performer shifts from speaking a line to singing the next without changing the character''s emotional intention. She is using what?','["Acting technique across spoken dialogue and song", "Box office skills", "Costume design", "Lighting design"]'::jsonb,0,'Acting links song and dialogue.','original'),
('117.319.c.1.C',3,'Why should an actor play an objective during a song?','["It replaces the melody", "A clear want makes the song feel like part of the story", "It makes the song longer", "It avoids singing"]'::jsonb,1,'Objectives motivate musical moments.','original'),
('117.319.c.1.D',2,'At a professional audition for a musical, performers are often asked to prepare what?','["A set design", "A lighting plot", "A song, sometimes a monologue and a dance combination", "A speech about weather"]'::jsonb,2,'Auditions often include song, acting and dance.','original'),
('117.319.c.1.D',2,'What should an auditioner bring to a professional musical theatre audition?','["A ticket stub", "A set model", "Pajamas", "A headshot, resume and prepared music"]'::jsonb,3,'Auditions require professional materials.','original'),
('117.319.c.1.E',3,'A student compares how a stage musical builds a story with songs to how a film musical may use editing and camera work. She is comparing what?','["Dramatic structure in stage and film musicals", "Posters", "Seat prices", "Parking"]'::jsonb,0,'Structure differs between media.','original'),
('117.319.c.1.E',3,'Which tool can a film musical use that a stage musical cannot?','["Live orchestra", "Close-up camera shots", "Live applause", "An intermission"]'::jsonb,1,'Film uses camera framing.','original'),
('117.319.c.1.F',2,'The area of the stage nearest the audience is called ___.','["Wings", "Upstage", "Downstage", "Orchestra pit"]'::jsonb,2,'Downstage is closest to the audience.','original'),
('117.319.c.1.F',2,'The group of singers who perform together in large ensemble numbers is called the ___.','["Pit", "Crew", "Cast crew", "Chorus"]'::jsonb,3,'The chorus supports principals in group numbers.','original'),
('117.319.c.1.G',3,'In a musical, the orchestra, lighting, choreography and set must all support the same story. This shows what?','["Theatrical elements depend on one another", "Design is optional", "Elements work alone", "Only singing matters"]'::jsonb,0,'All elements are interdependent.','original'),
('117.319.c.1.G',3,'If a dance number runs long, what else may need to change?','["Only the program", "Music, lighting cues and transitions", "Nothing", "Only tickets"]'::jsonb,1,'Changes ripple through the show.','original'),
('117.319.c.2.A',2,'Which practice protects the voice during a long rehearsal period for a musical?','["Yelling at the group", "Skipping rest days", "Hydrating and resting the voice", "Singing through pain"]'::jsonb,2,'Vocal care prevents injury.','original'),
('117.319.c.2.A',2,'Why wear proper shoes and warm up before a dance number?','["To avoid memorizing", "To be louder", "To look taller", "To prevent injuries to feet, ankles and legs"]'::jsonb,3,'Preparation and footwear prevent injury.','original'),
('117.319.c.2.B',2,'A student adds her own gesture to show a character''s excitement in a song. She is expressing what?','["Creativity in personal expression", "Ignoring the song", "Avoiding choices", "Copying exactly"]'::jsonb,0,'Creativity is personal expression.','original'),
('117.319.c.2.B',2,'What does creativity in musical theatre include?','["Repeating others exactly", "Making original choices in singing, acting and movement", "Avoiding risks", "Skipping rehearsal"]'::jsonb,1,'Creative choices personalize performance.','original'),
('117.319.c.2.C',3,'A student notes that the lead in a comic operetta is played with exaggeration, while the lead in a dramatic musical is played with realism. She is recognizing what?','["A music cue", "A costume error", "Characterization in musicals of different genres", "A staging mistake"]'::jsonb,2,'Genre shapes characterization.','original'),
('117.319.c.2.C',3,'Which detail helps an actor understand a character in a musical?','["The lobby layout", "The playbill ads", "The seat numbers", "The lyrics and dialogue that reveal wants and feelings"]'::jsonb,3,'Text reveals character.','original'),
('117.319.c.2.D',3,'A singer opens her mouth wide and directs the sound forward to project a clear tone. She is using proper ___.','["Vocal placement and production", "Stage placement", "Costume placement", "Light placement"]'::jsonb,0,'Placement affects tone.','original'),
('117.319.c.2.D',3,'Breath support in singing comes mainly from where?','["The shoulders", "The diaphragm and lower ribs", "The jaw", "The forehead"]'::jsonb,1,'Support is from the diaphragm.','original'),
('117.319.c.2.E',3,'An actor reads the lyrics aloud as a monologue to understand meaning before singing. She is interpreting lyrics for what?','["Lighting cues", "Set painting", "Characterization and vocalization", "Ticket sales"]'::jsonb,2,'Lyrics reveal character and guide singing.','original'),
('117.319.c.2.E',3,'A choreographer asks the ensemble to show the lyric ''rushing toward the future'' with a forward-driving phrase. This is interpreting lyrics in a choreographed ___.','["Marketing", "Ticketing", "Costuming", "Dance"]'::jsonb,3,'Movement can express lyrics.','original'),
('117.319.c.3.A',2,'Which action shows safe use of technical elements in a musical?','["Checking that microphones and cables are secured and out of the way", "Leaving cords across the stage", "Climbing without a spotter", "Skipping safety checks"]'::jsonb,0,'Safe handling prevents accidents.','original'),
('117.319.c.3.A',2,'Why is it important to follow safety rules around moving scenery during a musical?','["There is no risk", "Fast set changes can cause injuries if mishandled", "Scenery is soft", "Safety is optional"]'::jsonb,1,'Scenic movement needs caution.','original'),
('117.319.c.3.B',3,'The person who leads the singers and orchestra, teaching the music to the cast, is the ___.','["Stage manager", "Costume designer", "Musical director", "Choreographer"]'::jsonb,2,'The musical director prepares the music.','original'),
('117.319.c.3.B',3,'The choreographer is responsible for what?','["Painting the set", "Managing tickets", "Teaching the harmony", "Creating and teaching the dance movement"]'::jsonb,3,'Choreographers design dance.','original'),
('117.319.c.3.C',3,'A musical''s production plan might include rehearsal schedules, technical designs and blocking. This planning helps do what?','["Coordinate all production elements", "Cut the show", "Avoid work", "Remove actors"]'::jsonb,0,'Plans organize production.','original'),
('117.319.c.3.C',3,'Why is a costume plot useful in a musical production?','["It lists ticket buyers", "It tracks each costume piece and quick change for every performer", "It selects music", "It plans parking"]'::jsonb,1,'Costume plots track costumes.','original'),
('117.319.c.3.D',3,'A cast member sings in the chorus, learns choreography and supports the leads during a scene. She is collaborating to do what?','["Skip rehearsals", "Avoid performing", "Tell a story through live musical theatre", "Work alone"]'::jsonb,2,'Ensembles collaborate to tell a story.','original'),
('117.319.c.3.D',3,'Which action shows collaboration in a musical cast?','["Leaving rehearsal early", "Ignoring others", "Refusing blocking", "Learning harmonies together and giving each other notes"]'::jsonb,3,'Collaboration builds the show.','original'),
('117.319.c.4.A',3,'The popularity of vaudeville and operetta influenced early American musicals. This is an example of what?','["Historical and cultural influences on musical theatre", "A set change", "A casting mistake", "A stage injury"]'::jsonb,0,'Earlier forms shaped musicals.','original'),
('117.319.c.4.A',3,'Jazz and swing influenced the sound of many musicals in the 1920s and 1930s. This is a ___ influence.','["Culinary", "Cultural", "Medical", "Geographic only"]'::jsonb,1,'Popular music styles influence musicals.','original'),
('117.319.c.4.B',3,'Show Boat, premiering in 1927, is often cited as a landmark in American musical theatre because it did what?','["Used only dance", "Removed actors", "Integrated story, music and serious themes", "Removed songs"]'::jsonb,2,'It integrated story and song.','original'),
('117.319.c.4.B',3,'Which describes the musical as a uniquely American art form?','["It imitated one European form only", "It ignored music", "It had no story", "It blended many cultural traditions into a new theatrical form"]'::jsonb,3,'The American musical combined traditions.','original'),
('117.319.c.4.C',3,'The Golden Age of musical theatre in the 1940s and 1950s is known for productions that did what?','["Fully integrated songs, dance and drama", "Had no orchestra", "Avoided story", "Dropped dance"]'::jsonb,0,'Integrated musicals defined that era.','original'),
('117.319.c.4.C',3,'The rock musical emerged in the 1960s as a development in what?','["Cooking", "Musical theatre history and culture", "Architecture", "Sports"]'::jsonb,1,'Rock reflected changing culture.','original'),
('117.319.c.4.D',3,'A British musical that becomes a hit in New York and Tokyo shows musical theatre as an ___.','["Dead art", "Silent film", "International art form", "Local custom only"]'::jsonb,2,'Musicals travel worldwide.','original'),
('117.319.c.4.D',3,'Which London and Broadway hit helped spread musical theatre internationally?','["Hamlet", "A Doll''s House", "Our Town", "The Phantom of the Opera"]'::jsonb,3,'Phantom was a global hit.','original'),
('117.319.c.4.E',3,'A musical set in the Depression era shows musical theatre as what?','["A reflection of life in a particular time and place", "A news report", "Only fantasy", "Unrelated to history"]'::jsonb,0,'Musicals can reflect their settings.','original'),
('117.319.c.4.E',3,'Which musical reflects immigrant life in New York''s West Side during the 1950s?','["Oklahoma!", "West Side Story", "Cats", "Annie"]'::jsonb,1,'West Side Story is set among urban rival groups.','original'),
('117.319.c.4.F',3,'Film adaptations of stage musicals show the influence of what?','["Cooking shows", "Weather reports", "Musical theatre on film and television", "Sports"]'::jsonb,2,'Forms influence each other.','original'),
('117.319.c.4.F',3,'Live televised musicals show how musical theatre influences what?','["Agriculture", "Architecture", "Surveying", "Television programming"]'::jsonb,3,'Television adapts the musical.','original'),
('117.319.c.5.A',2,'During a musical, an audience member should do what?','["Silence phones and applaud at appropriate times", "Take flash photos", "Talk through songs", "Sing along loudly"]'::jsonb,0,'Etiquette respects performers.','original'),
('117.319.c.5.A',2,'When is applause especially appropriate at a musical?','["While actors speak", "After a song ends or at the curtain call", "During an orchestral hush", "During a quiet monologue"]'::jsonb,1,'Applause fits musical moments.','original'),
('117.319.c.5.B',3,'A student reflects on how singing, acting and dancing together shaped her growth as a performer. She is doing what?','["Avoiding reflection", "Copying others", "Evaluating herself as a creative being", "Ignoring feedback"]'::jsonb,2,'Self-evaluation supports growth.','original'),
('117.319.c.5.B',3,'Why is musical theatre called an art form?','["It needs no skill", "It is only a hobby", "It has no purpose", "It expresses ideas through combined music, drama and dance"]'::jsonb,3,'The combination creates art.','original'),
('117.319.c.5.C',3,'A peer says, ''Your phrasing in the second verse made the lyric clearer; maybe breathe earlier before the high note.'' This is ___.','["Constructive criticism", "Silence", "Insult", "Gossip"]'::jsonb,0,'Specific and helpful feedback.','original'),
('117.319.c.5.C',3,'When receiving feedback on your song, you should do what?','["Argue", "Listen openly and try the suggestion", "Ignore it", "Leave"]'::jsonb,1,'Openness improves performance.','original'),
('117.319.c.5.D',3,'A critic writes that the choreography in the finale reinforced the song''s joy and the ensemble stayed in tune. This review includes what?','["Vague opinion", "Prop list", "Precise, specific observations", "Gossip"]'::jsonb,2,'Specific details support evaluation.','original'),
('117.319.c.5.D',3,'Which review statement is most specific?','["I liked it", "It was long", "It was good", "The harmonies in the trio blended well and the staging clarified the plot"]'::jsonb,3,'Specific observations help readers.','original'),
('117.319.c.5.E',2,'A person who accompanies rehearsals and plays the music for a musical works as a ___.','["Rehearsal pianist or accompanist", "Costumer", "Lighting operator", "Ticket seller"]'::jsonb,0,'Accompanists support rehearsals.','original'),
('117.319.c.5.E',2,'Which job is available in musical theatre?','["Surveyor", "Choreographer", "Welder", "Pilot"]'::jsonb,1,'Choreographers work in musicals.','original'),
('117.319.c.5.F',3,'Public speaking and teamwork gained in musical theatre help students in which future setting?','["Only stage", "Only theatres", "College and careers outside theatre", "Nowhere"]'::jsonb,2,'Skills transfer.','original'),
('117.319.c.5.F',3,'How might singing in an ensemble help in a business career?','["It prevents learning", "It removes teamwork", "It avoids deadlines", "It builds listening, collaboration and confidence"]'::jsonb,3,'Collaboration skills transfer.','original'),
('117.319.c.5.G',3,'A student makes a slideshow about the history of musical theatre with clear headings and images. She is practicing what?','["Presenting information clearly and coherently with technology", "Disorganization", "Copying", "Silence"]'::jsonb,0,'Clear presentation matters.','original'),
('117.319.c.5.G',3,'Which tool helps a student present research about musicals?','["A hammer", "Presentation software", "A stopwatch", "A thermometer"]'::jsonb,1,'Slideshows aid presentation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
